let aiReturnRoute={tab:'home',page:'root',selected:1,client:0};function nav(t){if(t==='ai'&&tab!=='ai')aiReturnRoute={tab,page,selected,client};tab=t;page='root';render()}function head(title,sub='',back=false){$('#head').innerHTML=`<div class="top"><div class="row">${back?'<button class="back" onclick="goBack()" aria-label="返回">‹</button>':''}<div>${sub?`<div class="eyebrow">${sub}</div>`:''}<h1>${title}</h1></div></div>${back?'':'<div class="avatar">林</div>'}</div>`}
function goBack(){if(tab==='ai'&&page==='root'){persistAISession();({tab,page,selected,client}=aiReturnRoute);isGoingBack=true;routeHistory=[];render();return}const previous=routeHistory.pop();isGoingBack=true;if(previous){({tab,page,selected,client}=previous)}else page='root';render()}function openTask(id){detailSection='plan';selected=id;client=task().c;page='task';render()}function openClient(i){client=i;page='client';render()}function ask(prompt){tab='ai';page='root';render();if(prompt)respond(prompt)}
