function ensurePreparation(t){const defaults=['确认上次资料的反馈，并了解下一次交流需要准备的内容。','回顾上次交流，了解资料 A 的使用反馈，并确认后续需要补充的资料。'];if(t.preparation&&!defaults.includes(t.preparation))return;const previous=data.records.filter(r=>r.c===t.c).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0];t.preparation=`上次交流背景：${previous?.text||'此前围绕相关资料进行了交流，医生的具体反馈和需求仍需进一步确认。'}\n\n本次沟通重点：围绕“${t.title}”，进一步了解医生关注这些资料的具体场景，以及现有内容中仍不清楚、希望补充的部分。\n\n拟深入了解：医生最希望解决的具体问题是什么；需要哪些研究资料或说明；对后续补充内容的范围和时间有什么要求。\n\n预期结果：与医生确认优先需求、资料准备范围及下一次交流安排。`;save()}
