function refineFollowContent(id){const text=document.getElementById(id)?.value||'',c=client;window.showDoctorAgent({doctor:clients[c],plan:data.tasks.find(t=>t.id===selected&&t.c===c)||{title:'独立跟进',desc:''},records:data.records.filter(r=>r.c===c),plans:data.tasks.filter(t=>t.c===c),mode:'follow',initialDraft:text,onReview:(value,originalInput)=>{manualFollowOriginal=originalInput||'';const current=data.followDrafts?.[activeFollowDraftId];if(current&&originalInput)current.originalInput=originalInput;const el=document.getElementById(id);if(el){el.value=value;el.dispatchEvent(new Event('input',{bubbles:true}))}draft=value;render();toast('已带回跟进内容，请核对')},onOutline:generateOutline})}
