function recordPage(){if(!followAt)followAt=todayFollowTime();head('记录跟进','',true);$('#content').innerHTML=`${inputReference(manualFollowOriginal)}<div class="card"><div class="label">跟进医生</div><b>${clients[client].name}</b><p class="source">${clients[client].hospital} · ${clients[client].dept}</p>${followFields('manual-follow')}<div class="row spread"><div class="label">跟进内容</div><button class="ai-small" onclick="captureFollowFields('manual-follow');refineFollowContent('draft')">AI 辅助整理</button></div><textarea id="draft" aria-label="跟进内容" placeholder="记录交流要点、医生反馈与下一步行动…" oninput="draft=this.value">${esc(draft)}</textarea></div><button class="btn" onclick="submitRecord()">提交</button>`}

function sample(){draft=clinicalCases[client].follow;$('#draft').value=draft;$('#file-info').textContent='示例录音 · 拜访交流.m4a · 已载入';toast('已载入示例录音内容')}
function fileSelected(el){if(!el.files[0])return;$('#file-info').textContent='已选择：'+el.files[0].name+'（演示，不上传）';toast('请补充要点，或使用示例体验整理流程')}
function voiceDraft(){draft=(draft?draft+'\n':'')+clinicalCases[client].follow;$('#draft').value=draft;toast('已加入语音演示内容')}
function prepareReview(){captureFollowFields('manual-follow');if(!followAt)return toast('请选择拜访时间');draft=$('#draft').value.trim();if(!draft)return toast('请先填写内容或使用示例录音');page='review';render()}
function reviewPage(){const aiDraft=data.followDrafts?.[activeFollowDraftId];const t=data.tasks.find(t=>t.id===selected&&t.c===client&&!t.cancelled);head('记录跟进','',true);$('#content').innerHTML=`<div class="ai-review-notice">AI 已整理填写，请仔细核对跟进内容与拜访时间，确认无误后提交。</div>${inputReference(aiDraft?.originalInput)}<div class="card"><div class="label">跟进医生 · ${clients[client].name}</div>${t?`<p class="source">关联拜访：${esc(t.title)} · ${esc(t.scheduledDate||t.date)} ${esc(t.time)}</p>`:''}${followFields('review-follow')}<div class="row spread"><div class="label">跟进内容</div><button class="ai-small" onclick="captureFollowFields('review-follow');refineFollowContent('final-record')">AI 辅助整理</button></div><textarea id="final-record">${esc(draft)}</textarea></div>${t&&!t.done?`<div class="card"><span class="tag">已有拜访计划</span><label class="check"><input id="complete-old" type="checkbox"><span>标记完成：${esc(t.title)}<br><small class="muted">仅在该任务确实完成时勾选</small></span></label><input type="hidden" id="old-id" value="${t.id}"></div>`:''}<button class="btn" id="submit-record" onclick="submitRecord()">提交</button>`}
function submitRecord(){const existing=data.followDrafts?.[activeFollowDraftId];if(existing?.submitted){openHistory(existing.recordIndex);return}const manual=page==='record';captureFollowFields(manual?'manual-follow':'review-follow');if(!followAt)return toast('请选择拜访时间');const text=$(manual?'#draft':'#final-record').value.trim();if(!text)return toast('跟进内容不能为空');data.records.push({c:client,text,date:followAt.slice(0,10),visitAt:followAt,method:followMethod,planId:selected});const recordIndex=data.records.length-1;if(existing){existing.submitted=true;existing.recordIndex=recordIndex}if($('#complete-old')?.checked){const t=data.tasks.find(t=>t.id===Number($('#old-id').value));if(t)t.done=true}save();if(existing){chat.push({role:'assistant',html:`<div class="follow-submitted"><h3>已为你记录本次跟进</h3><p>${esc(clients[client].name)} · ${esc(clients[client].hospital)}</p><div class="follow-success-actions"><button class="btn secondary" onclick="openHistory(${recordIndex})">查看记录</button><button class="btn" onclick="planFromFollow(${recordIndex})">下一步拜访计划</button></div></div>`});tab='ai';page='root';render();return}page='success';render()}

function planFromFollow(recordIndex){const r=data.records[recordIndex];if(!r)return toast('未找到跟进记录');client=r.c;chatDoctor=r.c;activeSkill='新建拜访计划';planFillSession=false;planPendingInput='';newPlanDraft={c:String(r.c),title:'',date:'',time:'',content:''};const source=Object.values(data.followDrafts||{}).find(d=>d.recordIndex===recordIndex),purpose=source?.nextTitle||'拜访'+clients[r.c].name+'，确认本次跟进中的后续需求';chat.push({role:'user',html:'基于本次跟进，新建'+esc(clients[r.c].name)+'的拜访计划'},{role:'assistant',html:planFillResponse(purpose+'。上次交流：'+r.text)});tab='ai';page='root';render()}
function successPage(){head('处理结果','',true);const index=data.records.length-1;$('#content').innerHTML=`<div class="follow-success-result"><div class="follow-success-icon" aria-hidden="true"><svg viewBox="0 0 48 48" width="56" height="56" fill="none"><circle cx="24" cy="24" r="22" fill="#e7f6ed"/><path d="m14 24 7 7 14-15" stroke="#2d9559" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg></div><h2>跟进已保存</h2><p>${esc(clients[client].name)}的本次跟进记录已保存</p></div><div class="result-actionbar" aria-label="结果页操作"><button class="btn outline" onclick="newPlanForDoctor()">新增拜访计划</button><button class="btn outline" onclick="openHistory(${index})">查看跟进</button><button class="btn" onclick="nav('home')">返回工作台</button></div>`}
let promptDraft='';
const skillNames=['查资料','生成拜访提纲','记录跟进','新建拜访计划'];
function chooseSkill(name){if(agentBusy)return toast('请先停止当前处理，再切换技能');activeSkill=name;if(name==='新建拜访计划'&&!planFillSession){newPlanDraft={c:'',title:'',date:'',time:'',content:''};chatDoctor=null;planPendingInput=''}if(name==='记录跟进'){followAt='';followMethod='当面拜访';followPlanId=null;chatDoctor=null;followPendingInput=''}chat.push({role:'user',html:esc(name)},{role:'assistant',html:skillWelcome(name)});render()}
function setSkillExample(kind){const x=clinicalCases[chatDoctor??client];promptDraft=kind==='plan'?'明天下午两点，'+x.titles[0]+'，准备'+x.topic+'的一页摘要与原文目录。':x.follow;render();document.getElementById('prompt')?.focus()}
function selectedSkillGuide(i,name){const c=clients[i],latest=data.records.filter(r=>r.c===i).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0],isPlan=name==='新建拜访计划';return `<div class="skill-guide selected-skill-guide"><h3>${isPlan?'安排下一次拜访':'记录本次交流'}</h3><div class="skill-doctor-identity"><b>${esc(c.name)}</b><span>${esc(c.hospital)}</span><small>${esc(c.dept)}</small></div><p class="skill-guide-intro">${isPlan?'已关联这位医生，请在下方描述下次拜访安排，我会先与你确认。':'请用底部语音、文字或录音补充交流要点，我会填写跟进草稿。'}</p>${isPlan?'':`<dl class="skill-information-list">${isPlan?'<div><dt>拜访目的</dt><dd>希望讨论什么、解决什么问题</dd></div><div><dt>预计时间</dt><dd>哪一天、几点，未确定可稍后补齐</dd></div><div><dt>同行人员</dt><dd>由谁参加，是否有同事同行</dd></div><div><dt>沟通背景</dt><dd>上次提出的需求、本次希望深入了解的内容</dd></div>':'<div><dt>交流要点</dt><dd>医生反馈、明确提出的需求</dd></div><div><dt>拜访信息</dt><dd>跟进方式、实际时间，在草稿中核对</dd></div><div><dt>后续安排</dt><dd>需要补充什么、下一步如何跟进</dd></div>'}</dl>`}<button class="skill-example" onclick="setSkillExample('${isPlan?'plan':'follow'}')"><span>试着这样说</span><p>${isPlan?esc('明天下午两点，拜访'+c.name+'，确认随访工具样稿的字段与使用需求。'):esc(clinicalCases[i].follow)}</p><small>点击填入输入框，修改后发送</small></button></div>`}
let followPendingInput='';
function skillWelcome(name){const follow=name==='记录跟进',query=name==='查资料',newPlan=name==='新建拜访计划',doctorCards=query||newPlan;const copy=follow?'告诉我要记录哪位医生的哪次拜访，可用语音、文字或录音补充以下信息。我会先与你确认，再填入表单。':query?'告诉我想查哪位医生的资料，或点击下方医生。':newPlan?'请通过语音或文字告诉我想拜访哪位医生、下次拜访的目的、预计时间和同行人员，也可以补充沟通背景。下方近期医生仅为快捷入口。':'告诉我想处理哪次拜访，或点击下方拜访计划快捷开始。';const rows=data.tasks.filter(t=>{const d=t.scheduledDate||(t.date==='今天'?'2026-11-09':t.date==='明天'?'2026-11-10':t.date);return !t.cancelled&&d>='2026-11-09'&&d<=(follow?'2026-11-09':'2026-11-15')}).sort((a,b)=>a.time.localeCompare(b.time));const past=data.tasks.filter(t=>{const d=t.scheduledDate||(t.date==='今天'?'2026-11-09':t.date);return !t.cancelled&&t.done&&d>='2026-11-03'&&d<='2026-11-09'});const ids=[...new Set((newPlan?past:rows).map(t=>t.c))];return `<div class="skill-guide skill-entry-card"><h3>${icon('ai')}${name}</h3><p class="skill-guide-intro">${copy}</p>${follow?'<dl class="skill-information-list"><div><dt>时间与方式</dt><dd>哪天几点；当面、电话或网络拜访</dd></div><div><dt>交流与需求</dt><dd>聊了什么，医生的反馈和需求</dd></div><div><dt>后续行动</dt><dd>答应补充什么、何时完成</dd></div></dl>':''}${newPlan?'<dl class="skill-information-list"><div><dt>拜访目的</dt><dd>希望讨论什么、解决什么问题</dd></div><div><dt>预计时间</dt><dd>哪一天、几点，未确定可稍后补齐</dd></div><div><dt>同行人员</dt><dd>由谁参加，是否有同事同行</dd></div><div><dt>沟通背景</dt><dd>上次提出的需求、本次希望深入了解的内容</dd></div></dl>':''}<div class="skill-guide-label">${newPlan?'近期拜访医生':query?'近七天拜访医生':follow?'今日拜访计划':'近七天拜访计划'}</div><div class="skill-customer-options ${doctorCards?'':'visit-shortcuts'}">${doctorCards?ids.map(i=>`<button onclick="selectSkillCustomer(${i},'${name}')"><strong>${esc(clients[i].name)}</strong><span>${esc(clients[i].hospital)}</span><small>${esc(clients[i].dept)}</small></button>`).join('')||'<p>近七天暂无符合条件的医生，可直接输入医生姓名。</p>':rows.map(t=>`<button onclick="selectSkillVisit(${t.id},'${name}')"><strong>${esc(t.title)}</strong><span>${esc(clients[t.c].name)} · ${esc(clients[t.c].hospital)}</span><small>${esc(t.scheduledDate||t.date)} ${esc(t.time)}</small></button>`).join('')||'<p>暂无拜访计划，可直接描述需要处理的内容。</p>'}</div></div>`}

function selectSkillVisit(id,name){const t=data.tasks.find(t=>t.id===id&&!t.cancelled);if(!t)return;selected=t.id;client=t.c;chatDoctor=t.c;activeSkill=name;if(name==='记录跟进'){followCandidate=id;const pending=followPendingInput;followPendingInput='';confirmFollowVisit();if(pending)createFollowDraft(pending);return}if(name==='新建拜访计划'){newPlanDraft.c=String(t.c);chat.push({role:'user',html:esc('参考拜访：'+t.title+' · '+clients[t.c].name)},{role:'assistant',html:selectedSkillGuide(t.c,name)});render();return}respond(name==='查资料'?'查询“'+t.title+'”相关资料，医生'+clients[t.c].name:'为“'+t.title+'”生成拜访提纲，医生'+clients[t.c].name)}

function selectSkillCustomer(i,name){if(agentBusy)return;client=i;chatDoctor=i;activeSkill=name;if(name==='记录跟进'){chat.push({role:'user',html:esc(clients[i].name)});openFollowSelector(i);return}if(planFillSession||name==='新建拜访计划')newPlanDraft.c=String(i);if(name==='新建拜访计划'&&planPendingInput){const pending=planPendingInput;planPendingInput='';chat.push({role:'user',html:esc(clients[i].name)},{role:'assistant',html:planFillResponse(pending)});render();return}if(name==='查资料'||name==='生成拜访提纲'){respond(name==='查资料'?clients[i].name:'根据'+clients[i].name+'的历史记录生成拜访提纲');return}chat.push({role:'user',html:esc(clients[i].name)},{role:'assistant',html:selectedSkillGuide(i,name)});render()}
function exitSkill(){if(agentBusy)stopAgent();activeSkill='';render();toast('已退出技能，聊天记录已保留')}
function detectSkill(s){if(/(新建|创建|安排).*拜访/.test(s))return '新建拜访计划';if(/提纲|拜访准备/.test(s))return '生成拜访提纲';if(/记录.*跟进|填.*跟进|写跟进|录音/.test(s))return '记录跟进';if(/查|搜索|总结|回顾|资料|电话|号码/.test(s))return '查资料';return ''}
function chatPage(){chat=chat.filter(m=>!m.execution&&!m.html.includes('class="agent-execution"')&&!m.html.includes('class="execution-collapsed"'));head('AI 助手','',true);$('#content').innerHTML=`${chat.length?'':`<div class="ai-welcome"><div class="ai-welcome-mark" aria-hidden="true">✧</div><h2>你好，今天需要做什么？</h2><p>查资料、准备拜访或记录跟进，<br>直接告诉我。</p></div><div class="skills">${skillNames.map((name,i)=>`<button class="skill" onclick="chooseSkill('${name}')"><span>${['⌕','✧','▤','＋'][i]}</span>${name}<small>${['查询信息与历史跟进','了解客户，生成拜访提纲','整理拜访内容，保存记录','选择客户，安排拜访时间'][i]}</small></button>`).join('')}</div>`}${planFillSession?'<button class="ai-small plan-form-return" onclick="returnToPlanForm()">返回拜访计划表单 ›</button>':''}<div id="messages">${chat.map((x,i)=>`<div class="bubble ${x.role}" data-message-index="${i}">${x.html}</div>`).join('')}</div>`;const el=document.createElement('div');el.className='composer';el.innerHTML=`${chat.length?`<div class="composer-skills" aria-label="技能快捷入口">${skillNames.map(name=>`<button class="${activeSkill===name?'selected':''}" ${agentBusy?'disabled':''} onclick="chooseSkill('${name}')">${name}</button>`).join('')}</div>`:''}<div class="input-row"><button aria-label="长按语音输入" title="长按说话，松开发送（演示）" onclick="voiceChat()">♩</button><input id="prompt" value="${esc(promptDraft)}" oninput="promptDraft=this.value" ${agentBusy?'disabled':''} placeholder="长按说话" onkeydown="if(event.key==='Enter')send()"><button aria-label="导入音频" onclick="openAttachmentMenu()">＋</button><input type="file" id="chat-audio" accept="audio/*" hidden onchange="chatAudioSelected(this)"><button class="send" aria-label="发送" ${agentBusy?'disabled':''} onclick="send()">↑</button></div>`;$('#app').insertBefore(el,$('#nav'));}
function send(){const input=$('#prompt'),value=input.value.trim();if(value){promptDraft='';respond(value)}}function voiceChat(){if(chatDoctor===null){chat.push({role:'assistant',html:skillWelcome(activeSkill||'记录跟进')});render();return}respond(activeSkill==='新建拜访计划'?'明天14:00拜访'+clients[client].name+'，确认补充资料需求并了解反馈。':clinicalCases[client].follow);toast('语音演示：已输入示例交流内容')}
function openAttachmentMenu(){window.showAttachmentMenu({onAudio:()=>document.getElementById('chat-audio').click(),onVoice:voiceChat})}
function chatAudioSelected(el){const file=el.files?.[0];if(!file)return;chat.push({role:'user',html:'已导入录音：'+esc(file.name)},{role:'assistant',html:`录音文件已选择。本原型不上传或真实转写音频，你可以补充交流要点，或使用示例录音内容体验填写。<button class="ai-small" onclick="sampleChatRecording()">使用示例录音内容</button>`});render()}
function sampleChatRecording(){respond('本次交流了研究摘要，医生希望周五前补充相关资料，并在下次拜访时确认反馈。')}
let followFormSequence=0;
let followPlanId=null,followCandidate=null,followDoctorFilter='',activeFollowDraftId=null;
function openFollowSelector(doctor=null,pending=''){followCandidate=null;followDoctorFilter=doctor===null?'':String(doctor);promptDraft=/^(?:帮我)?(?:记录|整理|填写)(?:本次)?跟进(?:记录)?$/.test(pending)?'':pending;page='selectfollow';render()}
function setFollowCandidate(id){const top=$('#content').scrollTop;followCandidate=id;render();$('#content').scrollTop=top}
function selectFollowPage(){head('选择跟进的拜访','',true);const rows=data.tasks.filter(t=>!t.cancelled&&(followDoctorFilter===''||t.c===Number(followDoctorFilter))).slice().sort((a,b)=>{const key=t=>t.scheduledDate||(t.date==='今天'?'2026-11-09':t.date==='明天'?'2026-11-10':/^\d{4}-/.test(t.date)?t.date:'9999');return Number(a.done)-Number(b.done)||key(a).localeCompare(key(b))||a.time.localeCompare(b.time)});$('#content').innerHTML=`<p class="body-text">先关联本次交流对应的拜访，再补充沟通内容。已跟进的拜访也可以补充记录。</p><select class="field" aria-label="筛选拜访医生" onchange="followDoctorFilter=this.value;followCandidate=null;render()"><option value="" ${followDoctorFilter===''?'selected':''}>全部医生</option>${clients.map((c,i)=>`<option value="${i}" ${followDoctorFilter===String(i)?'selected':''}>${esc(c.name)}</option>`).join('')}</select><div class="follow-plan-options" role="radiogroup" aria-label="选择本次跟进的拜访">${rows.map(t=>`<button role="radio" aria-pressed="${followCandidate===t.id}" aria-checked="${followCandidate===t.id}" class="follow-plan-option ${followCandidate===t.id?'selected':''}" onclick="setFollowCandidate(${t.id})"><div class="row spread"><b>${esc(t.title)}</b><span class="follow-plan-status">${t.done?'已跟进':'待跟进'}</span></div><p>${esc(clients[t.c].name)} · ${esc(clients[t.c].hospital)}</p><small>${esc(clients[t.c].dept)}</small><div class="follow-plan-date">${esc(t.scheduledDate||t.date)} ${esc(t.time)}</div></button>`).join('')||'<p class="empty">没有可关联的拜访计划</p>'}</div><button class="btn" ${followCandidate===null?'disabled':''} onclick="confirmFollowVisit()">确认关联，补充交流内容</button>`}
function confirmFollowVisit(){const t=data.tasks.find(t=>t.id===followCandidate&&!t.cancelled);if(!t)return toast('请先选择拜访');selected=t.id;followPlanId=t.id;client=t.c;chatDoctor=t.c;activeSkill='记录跟进';followMethod='当面拜访';followAt=todayFollowTime();activeFollowDraftId=null;chat.push({role:'user',html:'本次跟进：'+esc(t.title)+' · '+esc(clients[t.c].name)},{role:'assistant',html:`<div class="linked-visit-card"><div class="linked-visit-top"><b>${esc(clients[t.c].name)}</b><button class="ai-small" onclick="openFollowSelector(${t.c})">更换</button></div><p class="linked-visit-doctor">${esc(clients[t.c].hospital)} · ${esc(clients[t.c].dept)}</p><h3>${esc(t.title)}</h3><p class="linked-visit-time">${esc(t.scheduledDate||t.date)} ${esc(t.time)}</p></div><p class="follow-input-hint">请补充拜访时间、方式（当面／电话／网络）、交流要点、医生需求和后续行动。我会先与你确认，再填入表单。</p>`});tab='ai';page='root';render()}
function cacheCurrentFollowDraft(){const el=$('#final-record'),d=data.followDrafts?.[activeFollowDraftId];if(!el||!d)return;d.content=el.value;d.method=$('#review-follow-method')?.value||d.method;d.at=$('#review-follow-at')?.value||'';d.nextTitle=$('#new-title')?.value||'';d.nextContent=$('#next-content')?.value||'';d.nextOutline=$('#next-outline')?.value||'';d.nextTime=$('#new-time')?.value||'';save()}
const followDemoCases=[{content:'本次与王医生沟通心衰患者居家管理的支持需求。医生反馈，现有宣教单文字多，患者复诊时经常说不清体重和症状变化；希望提供大字号、可连续记录七天的纸质表，并将体重、气促与水肿变化分栏。科室护士需要先确认可读性，异常情况提示由科室审核。已约定下次带两版样稿，请医生选择更适合出院教育的一版。',title:'拜访王医生，确认心衰居家记录表样稿',time:'2026-11-13 14:00'},{content:'本次与陈医生沟通糖尿病患者随访中的工具需求。医生反馈，患者往往只记录空腹血糖，复诊时难以回顾餐后血糖和低血糖相关情况；希望有一张可连续填写七天的记录表，区分空腹与餐后，保留用药及症状备注，并提供手机可查看的大字号版本。代表承诺先整理样稿，不采集患者个人信息；约定下次请医生及门诊护士一起核对字段和使用方式。',title:'拜访陈医生，核对七天血糖记录表的字段与样稿',time:'2026-11-13 16:30'},{content:'本次与刘医生确认心衰出院随访支持需求。医生反馈，患者常忘记复诊时间，现有宣教单没有清楚说明复诊时应携带哪些居家记录。希望将七天体重和症状记录、复诊日期及需携带资料放在同一张大字号清单上，患者填写区与医护询问区分开。已约定先提供纸质样稿，请科室护士试读，联系医护的提示由科室审核后使用。',title:'拜访刘医生，评审心衰出院随访清单样稿',time:'2026-11-13 10:00'}];
function todayFollowTime(){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());return parts.replace(' ','T')}
function structuredFollow(i){const text=followDemoCases[i].content,parts=text.split('。').filter(Boolean);return '【沟通主题】\n'+parts[0]+'。\n\n【医生反馈与需求】\n'+parts.slice(1,-1).join('。')+'。\n\n【后续行动】\n'+parts.at(-1)+'。'}
async function createFollowDraft(text,recognized=false){if(agentBusy)return;const t=data.tasks.find(t=>t.id===followPlanId),id='follow-'+Date.now();if(!t){openFollowSelector(client,text);return}if(!recognized){agentBusy=true;const status={role:'assistant',html:'<div class="follow-recognizing" role="status"><span></span>正在识别交流内容…</div>'};chat.push(status);render();await new Promise(resolve=>setTimeout(resolve,1100));chat=chat.filter(m=>m!==status);agentBusy=false}const example=followDemoCases[t.c];data.followDrafts=data.followDrafts||{};data.followDrafts[id]={id,c:t.c,planId:t.id,originalInput:text,content:structuredFollow(t.c),nextTitle:example.title,nextTime:example.time,nextContent:'带上'+['心衰居家记录表','七天血糖记录表','心衰出院随访清单'][t.c]+'的两版样稿，与医生及护士逐项核对字段、字号与填写方式；收集修改意见，确认下一版交付范围。',nextOutline:'1. 哪些字段必须保留，哪些可精简？\n2. 患者在什么场景填写，谁负责解释？\n3. 纸质版和手机查看版，哪种更适合门诊？\n4. 样稿由谁审核，何时反馈修改意见？',method:/电话/.test(text)?'电话拜访':/网络|线上|视频/.test(text)?'网络拜访':'当面拜访',at:todayFollowTime(),submitted:false};save();chat.push({role:'assistant',html:followConfirmation(id)});render()}

function followConfirmation(id){const d=data.followDrafts[id],t=data.tasks.find(t=>t.id===d.planId),c=clients[d.c],parts=followDemoCases[d.c].content.split('。').filter(Boolean),questions=[['现有居家记录表，哪些内容患者最难理解？','是否需要大字号、连续七天的体重和症状记录？'],['目前血糖记录遗漏哪些信息，影响复诊沟通？','记录表需要区分空腹、餐后，并保留哪些备注？'],['患者出院后最容易遗漏哪些复诊准备？','随访清单需要哪些记录项，患者和医护如何分工？']][d.c];return `<div class="follow-confirmation"><h3>请确认本次跟进</h3><p>我整理好了，请先核对关联的拜访和交流要点。确认前不会提交记录。</p><div class="linked-visit-card"><h4>${esc(t?.title||'待确认拜访')}</h4><p>${esc(c.name)} · ${esc(c.hospital)}</p><small>计划时间：${esc(t?.scheduledDate||t?.date||'待确认')} ${esc(t?.time||'')}</small></div><h4>沟通了哪些问题</h4><ul>${questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><h4>医生反馈与需求</h4><p>${esc(parts.slice(1,-1).join('。')+'。')}</p><h4>下一步行动</h4><p>${esc(parts.at(-1)+'。')}</p><p class="source">后续拜访尚未创建；保存跟进后可再单独安排。</p><p class="follow-confirm-question">以上是否对应你今天要记录的这次拜访？</p><button class="btn" onclick="openFollowDraft('${id}')">确认无误，下一步</button></div>`}
window.prepareScopedFollowDraft=function(plan,doctor,text){const ci=clients.findIndex(c=>c.name===doctor.name),id='scoped-follow-'+Date.now();data.followDrafts=data.followDrafts||{};data.followDrafts[id]={id,c:ci,planId:plan.id,originalInput:text,content:structuredFollow(ci),method:'当面拜访',at:todayFollowTime(),submitted:false};save();let html=followConfirmation(id).replace(`openFollowDraft('${id}')`,'acceptScopedFollow()').replace('确认无误','确认无误').replace(``,'');return {id,content:data.followDrafts[id].content,originalInput:text,html}};
function reselectFollowDraft(id){const d=data.followDrafts[id];if(!d)return;followPendingInput=d.originalInput||'';openFollowSelector(d.c)}
function openFollowDraft(id){const d=data.followDrafts?.[id];if(!d)return toast('未找到跟进草稿');if(d.submitted){openHistory(d.recordIndex);return}activeFollowDraftId=id;client=d.c;chatDoctor=d.c;selected=d.planId;followPlanId=d.planId;draft=d.content;followMethod=d.method;followAt=d.at||todayFollowTime();page='review';render()}
function followChatForm(text){const id=Date.now()+followFormSequence++,c=client,t=data.tasks.find(t=>t.id===followPlanId&&t.c===c&&!t.cancelled);return `<div class="ai-follow-draft"><h3>本次跟进 · 待核对</h3><p class="muted">已根据你提供的内容填写，确认前不会保存。</p><div class="label">跟进医生</div><p><b>${esc(clients[c].name)}</b> · ${esc(clients[c].hospital)}</p>${followFields('chat-follow-'+id)}<div class="row spread"><div class="label">跟进内容</div><button class="ai-small" onclick="refineFollowContent('ai-follow-${id}')">AI 辅助整理</button></div><textarea id="ai-follow-${id}" aria-label="AI 填写的跟进内容">${esc(text)}</textarea>${t?`<p class="source">关联拜访计划：${esc(t.title)}</p>`:'<p class="source">独立跟进记录 · 暂无关联待跟进计划</p>'}<button class="btn secondary" onclick="reviewChatFollow(${id},${c},${t?.id||0})">核对并继续</button></div>`}
function reviewChatFollow(id,c,planId){const value=document.getElementById('ai-follow-'+id)?.value.trim()||'';client=c;chatDoctor=c;activeSkill='记录跟进';openFollowSelector(c,value)}

let agentBusy=false,agentRun=0,chatDoctor=null;
function executionHtml(steps,current,finished=false,cancelled=false){return `${finished?'<details class="execution-collapsed"><summary>已完成处理 · 查看执行步骤</summary>':''}<div class="agent-execution" role="status" aria-live="polite"><div class="execution-heading"><span class="${finished||cancelled?'execution-static':'execution-spinner'}">${finished?'✓':cancelled?'—':''}</span><b>${cancelled?'已停止':finished?'处理完成':'正在处理'}${activeSkill?' · '+esc(activeSkill):''}</b><small>模拟执行</small></div><ol>${steps.map((step,i)=>`<li class="${finished||i<current?'is-done':i===current&&!cancelled?'is-running':'is-pending'}"><span class="execution-dot"></span>${esc(step)}<small>${finished||i<current?'完成':i===current&&!cancelled?'进行中':'等待'}</small></li>`).join('')}</ol>${!finished&&!cancelled?'<button class="ai-small" onclick="stopAgent()">停止处理</button>':''}</div>${finished?'</details>':''}`} 
function stopAgent(){agentRun++;agentBusy=false;const last=chat.findLast(m=>m.execution);if(last){last.html=executionHtml(last.steps,last.current,false,true);last.execution=false}render()}
async function respond(s){if(agentBusy)return toast('正在处理上一条请求，可以先停止处理');if(!s.trim())return;const linkedFollow=activeSkill==='记录跟进'&&data.tasks.some(t=>t.id===followPlanId&&!t.cancelled);const inferred=linkedFollow?null:detectSkill(s);if(inferred&&!((activeSkill==='记录跟进'||activeSkill==='新建拜访计划')&&!/^(查|搜索|生成|新建|创建|记录|帮我查)/.test(s)))activeSkill=inferred;else if(!activeSkill&&clients.some(c=>s.includes(c.name)))activeSkill='查资料';const namedIndex=clients.findIndex(c=>s.includes(c.name)||s.includes(c.name[0]+'医生'));if(namedIndex>=0&&!linkedFollow){client=namedIndex;chatDoctor=namedIndex}if(chatDoctor!==null)client=chatDoctor;if(activeSkill==='记录跟进'&&(!followPlanId||!data.tasks.some(t=>t.id===followPlanId&&t.c===client&&!t.cancelled))){chat.push({role:'user',html:esc(s)});agentBusy=true;const status={role:'assistant',html:'<div class="follow-recognizing" role="status"><span></span>正在识别医生、拜访计划与交流内容…</div>'};chat.push(status);render();await new Promise(resolve=>setTimeout(resolve,1100));chat=chat.filter(m=>m!==status);agentBusy=false;const di=clients.findIndex(c=>s.includes(c.name)||s.includes(c.name[0]+'医生'));let matches=data.tasks.filter(t=>!t.cancelled&&(s.includes(t.title)||(di>=0&&t.c===di&&(t.scheduledDate==='2026-11-09'||t.date==='今天'||t.date==='2026-11-09'))));if(matches.length>1){const time=s.match(/(\d{1,2})[:：点](\d{2})?/);if(time){const h=Number(time[1])+(s.includes('下午')&&Number(time[1])<12?12:0);matches=matches.filter(t=>t.time===String(h).padStart(2,'0')+':'+(time[2]||'00'))}}if(matches.length===1){const t=matches[0];selected=t.id;followPlanId=t.id;client=t.c;chatDoctor=t.c;createFollowDraft(s,true);return}followPendingInput=s;chat.push({role:'assistant',html:`<div class="follow-confirmation"><h3>请确认识别结果</h3><dl class="skill-information-list"><div><dt>跟进医生</dt><dd>${di>=0?esc(clients[di].name+' · '+clients[di].hospital):'尚未确定，请补充医生姓名'}</dd></div><div><dt>关联拜访</dt><dd>${matches.length>1?'存在多次拜访，请补充时间或目的':'暂未找到对应计划，请补充拜访目的或时间'}</dd></div></dl><h4>已收到的交流内容</h4><p>${esc(s)}</p><p>请先确认医生与拜访计划，我会保留这段输入，并接着整理沟通问题、医生需求和后续行动。</p></div>`+skillWelcome('记录跟进')});render();return}if(chatDoctor===null&&activeSkill){if(activeSkill==='新建拜访计划')planPendingInput=s;chat.push({role:'user',html:esc(s)},{role:'assistant',html:skillWelcome(activeSkill)});render();return}if(chatDoctor!==null)client=chatDoctor;chat.push({role:'user',html:esc(s)});completeResponse(s)}
function doctorDossier(i){const c=clients[i],records=data.records.filter(r=>r.c===i).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')),plans=data.tasks.filter(t=>t.c===i&&!t.cancelled).sort((a,b)=>Number(a.done)-Number(b.done)),needs=records.filter(r=>/需求|希望|需要|补充|问题/.test(r.text)),p=plans[0];return `<div class="doctor-dossier"><h3>${esc(c.name)} · 医生简报</h3><small>基于已保存资料整理 · ${new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}</small><h4>医生概况</h4><p>${esc(c.hospital)} · ${esc(c.dept)}</p><a href="tel:${c.phone.replaceAll(' ','')}">${esc(c.phone)}</a><h4>近期沟通摘要</h4>${records.slice(0,3).map(r=>`<div class="dossier-entry"><small>${esc(r.date||'未标日期')}</small><p>${esc(r.text)}</p></div>`).join('')||'<p>暂无已保存的跟进记录</p>'}<h4>关注与需求</h4>${needs.slice(0,2).map(r=>`<p>${esc(r.text)}</p>`).join('')||'<p>现有记录未明确列出需求，需进一步确认。</p>'}<h4>近期拜访重点</h4>${p?`<p><b>${esc(p.title)}</b></p><p>${esc(p.scheduledDate||p.date)} ${esc(p.time)} · ${p.done?'已跟进':'待跟进'}</p><p>${esc(p.preparation||p.desc||'暂无补充内容')}</p>`:'<p>暂无关联拜访计划</p>'}<h4>建议关注的问题</h4><p>${esc(clinicalCases[i].questions.slice(0,2).join("；"))}</p><small>以上为示例推导建议，不代表医生已表达的需求。</small><details class="answer-evidence"><summary>信息依据 · 医生档案、${records.length} 条跟进记录、${plans.length} 条拜访计划</summary><p>${esc(c.name+' · '+c.hospital+' · '+c.dept)}</p>${records.map(r=>`<div><b>${esc(r.date||'未标日期')} · 跟进记录</b><p>${esc(r.text)}</p></div>`).join('')}${plans.map(t=>`<div><b>${esc(t.title)}</b><p>${esc(t.scheduledDate||t.date)} ${esc(t.time)}</p></div>`).join('')}</details><button class="ai-small" onclick="openClient(${i})">查看医生档案 ›</button></div>`}
function completeResponse(s){s=(activeSkill?activeSkill+' ':'')+s;const found=clients.findIndex(c=>s.includes(c.name));if(activeSkill==='记录跟进'&&followPlanId){const linked=data.tasks.find(t=>t.id===followPlanId);if(linked)client=linked.c}else if(found>=0)client=found;const c=clients[client];if(activeSkill==='新建拜访计划'){const text=s.replace(/^新建拜访计划\s*/,'').trim();chat.push({role:'assistant',html:text===c.name?selectedSkillGuide(client,activeSkill):planFillResponse(s)});render();return}if(activeSkill==='查资料'&&found>=0&&!/电话|号码/.test(s)){chat.push({role:'assistant',html:doctorDossier(client)});render();return}let html='';if(activeSkill==='新建拜访计划'){html=`为 ${c.name} 创建拜访计划：<div class="label">任务内容</div><input class="field" id="quick-title" placeholder="例如：周五核对糖尿病肾病研究摘要"><button class="btn secondary" style="margin-top:10px" onclick="quickTask()">创建拜访计划</button>`}else if(activeSkill==='记录跟进'){const content=s.replace(/^记录跟进\s*/,'').trim();createFollowDraft(content);return}else if(activeSkill==='生成拜访提纲'){const p=data.tasks.find(t=>t.id===selected&&t.c===client)||data.tasks.find(t=>t.c===client&&!t.done)||data.tasks.find(t=>t.c===client);html=`<h3>${esc(c.name)} · 拜访提纲</h3><h4>沟通目标</h4><p>${esc(p?.title||'了解医生当前关注的问题与资料需求')}</p><h4>沟通背景</h4><p>${esc(data.records.filter(r=>r.c===client).sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0]?.text||'暂无已保存的历史记录')}</p><h4>建议调研问题</h4><ol>${clinicalCases[client].questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><p>以上为基于现有资料的示例建议，请结合实际交流调整。</p>`;}else if(/电话|号码/.test(s)){html=`找到客户档案中的联系电话：<div class="card" style="margin-top:10px"><b>${c.name}</b><p class="muted">${c.hospital} · ${c.dept}</p><a href="tel:${c.phone.replaceAll(' ','')}" style="color:#147b70">${c.phone}</a></div><button class="ai-small" onclick="page='client';render()">查看客户档案 ›</button><div class="source">来源：示例客户基本信息</div>`}else{html=`当前客户：<b>${c.name}</b>，${c.hospital}。<br>${esc(clinicalCases[client].records[0])}<div class="source">依据：示例客户资料与历史跟进</div><button class="btn secondary" style="margin-top:12px" onclick="page='client';render()">查看客户资料</button><div class="label">也可以选择其他客户</div>${clients.map((v,i)=>`<button class="tag" style="margin:4px" onclick="client=${i};respond('查询${v.name}的历史资料')">${v.name}</button>`).join('')}`}if(activeSkill==='查资料'||activeSkill==='生成拜访提纲'){const sources=[{title:'客户档案',text:c.name+' · '+c.hospital+' · '+c.dept},...data.records.filter(r=>r.c===client).slice(-2).map(r=>({title:'跟进记录 · '+(r.date||'未标日期'),text:r.text}))];html+=`<details class="answer-evidence"><summary>依据 · ${sources.length} 项</summary>${sources.map(x=>`<div><b>${esc(x.title)}</b><p>${esc(x.text)}</p></div>`).join('')}<small>示例回答；推导建议请与原始记录核对。</small></details>`}chat.push({role:'assistant',html});render()}
function quickTask(){const el=$('#quick-title'),title=el?.value.trim();if(!title)return toast('请填写任务内容');data.tasks.push({id:Date.now(),c:client,title,time:'待确定',date:'今天',kind:'跟进任务',desc:title,done:false});save();chat.push({role:'assistant',html:'✓ 拜访计划已创建，已关联 '+clients[client].name+'。<button class="btn secondary" onclick="nav(\'home\')">查看工作台</button>'});render()}
let routeHistory=[],lastRoute=null,isGoingBack=false;
let chatRenderedCount=0,chatRenderFrame=0,chatWasVisible=false;
function positionChat(scrollTop,alignNew){const frame=++chatRenderFrame;requestAnimationFrame(()=>{if(frame!==chatRenderFrame||tab!=='ai'||page!=='root')return;const scroller=$('#content'),last=document.querySelector('#messages > .bubble:last-child');if(!last)return;let spacer=document.getElementById('chat-bottom-space');if(!spacer){spacer=document.createElement('div');spacer.id='chat-bottom-space';document.getElementById('messages').appendChild(spacer)}spacer.style.height=Math.max(0,scroller.clientHeight-last.offsetHeight-24)+'px';const target=alignNew?last.getBoundingClientRect().top-scroller.getBoundingClientRect().top+scroller.scrollTop-12:scrollTop;scroller.scrollTo({top:Math.max(0,target),behavior:'instant'});});}
function render(){cacheCurrentFollowDraft();const isChat=tab==='ai'&&page==='root',oldScroll=chatWasVisible?$('#content').scrollTop:0,alignNew=isChat&&(!chatWasVisible||chat.length!==chatRenderedCount);window.businessContext={tab,page,aiFollowDraft:page==='review'&&!!activeFollowDraftId,clients,data,client,onClient:openClient,onTask:openTask,onFollow:followFromList,onRecord:openPlanRecords,onHistory:openHistory,onAI:()=>{const c=client;window.showDoctorAgent({doctor:clients[c],plan:data.tasks.find(t=>t.c===c)||task(),records:data.records.filter(r=>r.c===c),plans:data.tasks.filter(t=>t.c===c),onOutline:generateOutline})}};document.body.classList.toggle('visit-detail-route',page==='task');document.body.classList.toggle('ai-route',tab==='ai'&&page==='root');const current={tab,page,selected,client};if(lastRoute&&!isGoingBack){if(page==='root')routeHistory=[];else if(lastRoute.page!==page||lastRoute.client!==client||lastRoute.selected!==selected)routeHistory.push(lastRoute)}isGoingBack=false;lastRoute=current;document.body.classList.toggle('detail-route',page!=='root');document.body.classList.remove('form-route');window.applyUIUpdates(()=>{renderLegacy();if(!(tab==='home'&&page==='root'))window.upgradeBusinessViews({tab,onNav:nav,onBack:goBack});});document.body.classList.toggle('ai-empty',isChat&&chat.length===0);if(isChat){positionChat(oldScroll,alignNew);persistAISession()}chatWasVisible=isChat;chatRenderedCount=chat.length;}
render();


// Form drafts: persist locally without submitting business records.
function rememberFormDraft(){
 if(!['record','review','newplan'].includes(page))return null;
 let d;
 if(page==='newplan'){
  if(!document.getElementById('new-plan-doctor'))return null;
  captureNewPlan();d={kind:'plan',values:{...newPlanDraft},updatedAt:Date.now()};
 }else{
  const el=document.getElementById(page==='record'?'draft':'final-record');if(!el)return null;
  captureFollowFields(page==='record'?'manual-follow':'review-follow');draft=el.value;
  d={kind:'follow',page,client,selected,content:draft,method:followMethod,at:followAt,aiDraftId:activeFollowDraftId,originalInput:manualFollowOriginal,complete:!!document.getElementById('complete-old')?.checked,updatedAt:Date.now()};
 }
 data.formDrafts=data.formDrafts||{};data.formDrafts[d.kind]=d;save();return d;
}
function saveFormDraft(){const d=rememberFormDraft();if(d)toast('草稿已保存，可稍后继续填写')}
function restoreFormDraft(kind){const d=data.formDrafts?.[kind];if(!d)return toast('暂无草稿');if(kind==='plan'){newPlanDraft={...d.values};page='newplan'}else{client=d.client;selected=d.selected;draft=d.content;followMethod=d.method;followAt=d.at;activeFollowDraftId=d.aiDraftId;manualFollowOriginal=d.originalInput||'';page=d.page;if(activeFollowDraftId&&data.followDrafts?.[activeFollowDraftId])Object.assign(data.followDrafts[activeFollowDraftId],{content:draft,method:followMethod,at:followAt})}render();if(kind==='follow'&&document.getElementById('complete-old'))document.getElementById('complete-old').checked=d.complete}
function draftFeedback(d){return `<div class="draft-saved-card"><h3>草稿已保存</h3><p>你刚才中断了${d.kind==='follow'?'跟进记录':'拜访计划'}的提交，填写内容已保存为草稿，尚未提交。</p><button class="btn" onclick="restoreFormDraft('${d.kind}')">查看草稿</button></div>`}
const originalDraftBack=goBack;
goBack=function(){const d=rememberFormDraft();originalDraftBack();if(!d)return;if(tab==='ai'&&page==='root'){chat.push({role:'assistant',html:draftFeedback(d)});render()}else{page='draftsaved';window.lastSavedFormDraft=d;render()}};
const originalDraftLegacy=renderLegacy;
renderLegacy=function(){if(page==='draftsaved'){head('草稿已保存','',true);document.querySelector('.composer')?.remove();$('#content').innerHTML=draftFeedback(window.lastSavedFormDraft)+'<button class="btn secondary" onclick="page=\'root\';tab=\'home\';render()">返回工作台</button>';return}originalDraftLegacy();if(['record','review','newplan'].includes(page)){const btn=document.createElement('button');btn.className='btn secondary';btn.textContent='保存草稿';btn.setAttribute('onclick','saveFormDraft()');const submit=[...$('#content').children].find(e=>e.matches('button.btn')&&/submitRecord|saveNewPlan/.test(e.getAttribute('onclick')||''));if(submit)submit.before(btn)}if(page==='root'&&tab==='home'&&Object.keys(data.formDrafts||{}).length){const box=document.createElement('div');box.className='saved-draft-entry';box.innerHTML=Object.keys(data.formDrafts).map(k=>`<button onclick="restoreFormDraft('${k}')">${k==='follow'?'跟进记录':'拜访计划'}草稿 · 继续填写 ›</button>`).join('');$('#app').appendChild(box)}};
const originalDraftRender=render;
render=function(){document.querySelector('.saved-draft-entry')?.remove();originalDraftRender()};
const originalDraftSubmit=submitRecord;
submitRecord=function(){const n=data.records.length;originalDraftSubmit();if(data.records.length>n&&data.formDrafts){delete data.formDrafts.follow;save()}};
const originalDraftPlanSave=saveNewPlan;
saveNewPlan=function(){const n=data.tasks.length;originalDraftPlanSave();if(data.tasks.length>n&&data.formDrafts){delete data.formDrafts.plan;save()}};
let formDraftTimer;
document.addEventListener('input',()=>{if(['record','review','newplan'].includes(page)){clearTimeout(formDraftTimer);formDraftTimer=setTimeout(rememberFormDraft,350)}},true);
document.addEventListener('change',()=>{if(['record','review','newplan'].includes(page))rememberFormDraft()},true);
window.addEventListener('pagehide',rememberFormDraft);

if(data.formDrafts&&Object.keys(data.formDrafts).length)render();
